#!/usr/bin/env bash
# hermes-update spike, generated by build.sh: stub.py and render.py are inlined.
set -u
W=$(mktemp -d)
cat > $W/stub.py <<'PYSTUB'
"""Two loopback stubs for the hermes spike, logging every request as JSON lines.

127.0.0.1:1934 stands in for ov_auth_proxy (OpenViking API).
127.0.0.1:8080 stands in for Bifrost (OpenAI chat completions): it answers the
first turn with a viking_search tool call and the next with SPIKE-DONE.
"""

import json
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

LOG = sys.argv[1] if len(sys.argv) > 1 else "/tmp/requests.jsonl"
lock = threading.Lock()

MEMORY = {
    "uri": "viking://user/jasper/memories/spike-probe.md",
    "abstract": "SPIKE-MEMORY: the lab account remembers the spike probe.",
    "score": 0.93,
    "context_type": "memory",
}


def log(port, handler, body):
    entry = {
        "port": port,
        "method": handler.command,
        "path": handler.path,
        "headers": {k.lower(): v for k, v in handler.headers.items()},
        "body": body[:2000].decode("utf-8", "replace"),
    }
    with lock, open(LOG, "a") as f:
        f.write(json.dumps(entry) + "\n")


class Base(BaseHTTPRequestHandler):
    port = 0

    def log_message(self, *args):
        pass

    def _body(self):
        n = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(n) if n else b""

    def _json(self, obj, status=200):
        data = json.dumps(obj).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def handle_any(self):
        body = self._body()
        log(self.port, self, body)
        self.respond(body)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = handle_any


class Viking(Base):
    port = 1934

    def respond(self, body):
        p = self.path.split("?")[0]
        if p == "/health":
            return self._json({"status": "ok", "healthy": True, "version": "0.4.17"})
        if p.startswith("/api/v1/search/"):
            return self._json({"status": "ok", "result": {
                "memories": [MEMORY], "resources": [], "skills": [], "total": 1}})
        if p == "/api/v1/fs/ls":
            return self._json({"status": "ok", "result": []})
        if p.startswith("/api/v1/sessions"):
            return self._json({"status": "ok", "result": {"session_id": "spike", "messages": []}})
        if p == "/api/v1/system/status":
            return self._json({"status": "ok", "result": {"initialized": True, "user": "jasper"}})
        return self._json({"status": "ok", "result": {}})


def completion(content=None, tool_call=None):
    msg = {"role": "assistant", "content": content}
    if tool_call:
        msg["tool_calls"] = [tool_call]
    return {
        "id": "chatcmpl-spike", "object": "chat.completion", "created": 0,
        "model": "ollama/deepseek-v4.1-flash",
        "choices": [{"index": 0, "message": msg,
                     "finish_reason": "tool_calls" if tool_call else "stop"}],
        "usage": {"prompt_tokens": 10, "completion_tokens": 5, "total_tokens": 15},
    }


class Bifrost(Base):
    port = 8080

    def respond(self, body):
        p = self.path.split("?")[0]
        if p.endswith("/models"):
            return self._json({"object": "list", "data": [
                {"id": "ollama/deepseek-v4.1-flash", "object": "model", "context_length": 128000}]})
        if not p.endswith("/chat/completions"):
            return self._json({"error": {"message": "stub: unsupported " + p}}, 404)
        req = json.loads(body or b"{}")
        msgs = req.get("messages", [])
        tools = [t.get("function", {}).get("name") for t in req.get("tools") or []]
        saw_tool = any(m.get("role") == "tool" for m in msgs)
        if not saw_tool and "viking_search" in tools:
            resp = completion(tool_call={"id": "call_spike", "type": "function", "function": {
                "name": "viking_search", "arguments": json.dumps({"query": "spike probe"})}})
        elif saw_tool:
            resp = completion(content="SPIKE-DONE")
        else:
            resp = completion(content="NO-VIKING-TOOL tools=" + ",".join(t or "" for t in tools))
        if req.get("stream"):
            return self._stream(resp)
        return self._json(resp)

    def _stream(self, resp):
        msg = resp["choices"][0]["message"]
        delta = {"role": "assistant"}
        if msg.get("content"):
            delta["content"] = msg["content"]
        if msg.get("tool_calls"):
            delta["tool_calls"] = [dict(tc, index=0) for tc in msg["tool_calls"]]
        chunks = [
            {"id": resp["id"], "object": "chat.completion.chunk", "created": 0, "model": resp["model"],
             "choices": [{"index": 0, "delta": delta, "finish_reason": None}]},
            {"id": resp["id"], "object": "chat.completion.chunk", "created": 0, "model": resp["model"],
             "choices": [{"index": 0, "delta": {}, "finish_reason": resp["choices"][0]["finish_reason"]}],
             "usage": resp["usage"]},
        ]
        self.send_response(200)
        self.send_header("Content-Type", "text/event-stream")
        self.end_headers()
        for c in chunks:
            self.wfile.write(b"data: " + json.dumps(c).encode() + b"\n\n")
        self.wfile.write(b"data: [DONE]\n\n")
        self.wfile.flush()


if __name__ == "__main__":
    servers = [ThreadingHTTPServer(("127.0.0.1", 1934), Viking),
               ThreadingHTTPServer(("127.0.0.1", 8080), Bifrost)]
    for s in servers[1:]:
        threading.Thread(target=s.serve_forever, daemon=True).start()
    servers[0].serve_forever()
PYSTUB
cat > $W/render.py <<'PYRENDER'
"""Render the hermes data dir the `config` prestart task writes, from hermes.hcl.

usage: render.py HERMES_HCL OUT_DIR
Takes config.yaml and the bifrost model-provider files verbatim from the
jobspec's template heredocs, filling the few Terraform variables they use.
"""

import re
import sys
from pathlib import Path

hcl = Path(sys.argv[1]).read_text()
out = Path(sys.argv[2])

templates = dict(
    (dest, data)
    for data, dest in re.findall(
        r'data = <<EOF\n(.*?)\nEOF\n\s*\n\s*destination = "([^"]+)"', hcl, re.S
    )
)
need = [
    "local/config.yaml",
    "local/model-providers/bifrost/__init__.py",
    "local/model-providers/bifrost/plugin.yaml",
]
missing = [n for n in need if n not in templates]
if missing:
    sys.exit(f"render: templates not found in jobspec: {missing}")

def fill(text: str) -> str:
    text = text.replace("${hermes_dashboard_public_url}", "http://127.0.0.1:9119")
    return text.replace("$${", "${")

files = {
    "config.yaml": fill(templates["local/config.yaml"]),
    "plugins/model-providers/bifrost/__init__.py": fill(templates[need[1]]),
    "plugins/model-providers/bifrost/plugin.yaml": fill(templates[need[2]]),
    # The OPENVIKING_* lines setup.sh writes to /opt/data/.env, with the
    # values services.tf passes (openviking_proxy_placeholder, _account, _user).
    ".env": "\n".join([
        "OPENVIKING_API_KEY=unused-the-sidecar-supplies-the-token",
        "OPENVIKING_ACCOUNT=lab",
        "OPENVIKING_USER=jasper",
        "OPENVIKING_ENDPOINT=http://127.0.0.1:1934",
        "HERMES_YOLO_MODE=true",
        "HERMES_HOME=/opt/data",
        "BIFROST_API_KEY=spike-bifrost-key",
    ]) + "\n",
}
for rel, body in files.items():
    p = out / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(body)
for d in ["sessions", "memories", "cron", "hooks", "logs", "skills"]:
    (out / d).mkdir(exist_ok=True)
print("render: wrote", ", ".join(sorted(files)))
PYRENDER
# Risk 2 of hermes-update-0-23: the image is built the way the repo Dockerfile
# lays out memory plugins (catalog plugin 2.1.1 copy + our openviking_tools
# wrapper), but FROM v0.23.4. apt (jq/chromium) and faster-whisper layers are
# left out: they do not touch the memory path.
ROOT=$(git rev-parse --show-toplevel)
DF=$ROOT/deployments/applications/services/hermes/Dockerfile
mkdir -p $W/ctx
cp -r $ROOT/deployments/applications/services/hermes/openviking_tools $W/ctx/
{
  echo 'FROM nousresearch/hermes-agent:v0.23.4'
  echo 'USER root'
  sed -n '/^ARG OPENVIKING_PLUGIN_SHA/,/^$/p' $DF
  grep '^COPY openviking_tools' $DF
} > $W/ctx/Dockerfile
echo "== spike Dockerfile"; cat $W/ctx/Dockerfile
grep -q 9f150ece247ad683494ab172d738023bd6dc6170 $W/ctx/Dockerfile || { echo "pin missing"; exit 2; }
IMG=hermes-spike-ov:0.23.4
docker build -q -t $IMG $W/ctx || exit 2
ID=hspk$$
VOL=$ID-data
KEY=unused-the-sidecar-supplies-the-token
FAIL=0

check() { if eval "$2"; then echo "PASS: $1"; else echo "FAIL: $1"; FAIL=1; fi; }
cleanup() {
  docker rm -f $ID-h $ID-s >/dev/null 2>&1
  docker volume rm $VOL >/dev/null 2>&1
  docker network rm $ID-offline >/dev/null 2>&1
}
trap cleanup EXIT

start_hermes() {
  docker run -d --name $1 --network container:$2 -v $VOL:/opt/data --shm-size 1g \
    -e HERMES_HOME=/opt/data -e HERMES_YOLO_MODE=true \
    -e OPENVIKING_ENDPOINT=http://127.0.0.1:1934 -e OPENVIKING_API_KEY=$KEY \
    -e OPENVIKING_ACCOUNT=lab -e OPENVIKING_USER=jasper \
    -e API_SERVER_ENABLED=true -e API_SERVER_HOST=0.0.0.0 -e API_SERVER_KEY=7f3c9a1e5b2d4f6a8c0e9b7d5a3f1c2e \
    -e GATEWAY_HEALTH_TIMEOUT=5 -e BIFROST_API_KEY=spike-bifrost-key \
    $IMG hermes gateway run >/dev/null
}

wait_gateway() {
  for _ in $(seq 1 90); do
    code=$(docker exec $1 curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:8642/health 2>/dev/null)
    [ "$code" != "000" ] && [ -n "$code" ] && { echo "gateway $1 answered /health with $code"; return 0; }
    sleep 2
  done
  echo "gateway $1 never answered"; docker logs --tail 80 $1; return 1
}

ask() {
  docker exec $1 curl -sS -m 600 http://127.0.0.1:8642/v1/chat/completions \
    -H 'Authorization: Bearer 7f3c9a1e5b2d4f6a8c0e9b7d5a3f1c2e' -H 'Content-Type: application/json' \
    -d '{"model":"hermes-agent","messages":[{"role":"user","content":"Search OpenViking for the spike probe."}]}'
}

stub_log() { docker exec $1 cat /tmp/requests.jsonl 2>/dev/null; }

searched_with_key() {
  stub_log $1 | python3 -I -c '
import json, sys
hits = [e for e in map(json.loads, sys.stdin)
        if e["port"] == 1934 and e["path"].startswith("/api/v1/search/")
        and e["headers"].get("x-api-key") == sys.argv[1]]
print(len(hits), "search request(s) with the placeholder key")
sys.exit(0 if hits else 1)
' "$KEY"
}

all_logs() { docker logs $1 2>&1; docker exec $1 sh -c 'cat /opt/data/logs/*.log 2>/dev/null'; }

echo "== render the config task output from hermes.hcl"
python3 -I $W/render.py $ROOT/deployments/applications/services/hermes.hcl $W/data || exit 2
grep -n 'provider: "openviking_tools"' $W/data/config.yaml || { echo "config lacks openviking_tools"; exit 2; }
docker volume create $VOL >/dev/null
tar -C $W/data -cf - . | docker run --rm -i -v $VOL:/opt/data --entrypoint sh $IMG \
  -c 'tar xf - -C /opt/data && chown -R hermes:hermes /opt/data' || exit 2

echo "== gateway on a network with no route off the host"
docker network create --internal $ID-offline >/dev/null
docker create --name $ID-s --network $ID-offline --entrypoint /opt/hermes/.venv/bin/python3 $IMG -u /stub.py /tmp/requests.jsonl >/dev/null
docker cp $W/stub.py $ID-s:/stub.py
docker start $ID-s >/dev/null
start_hermes $ID-h $ID-s
wait_gateway $ID-h || exit 2
R=$(ask $ID-h); echo "reply: $R" | cut -c1-600
echo "-- hermes memory status"
docker exec -u hermes -e HERMES_HOME=/opt/data $ID-h hermes memory status 2>&1 | tail -20
check "memory status shows openviking_tools active" "docker exec -u hermes -e HERMES_HOME=/opt/data $ID-h hermes memory status 2>&1 | grep -q 'openviking_tools.*active'"
check "reply came back after a viking_search result" "echo \"\$R\" | grep -q SPIKE-DONE"
check "viking_search reached the stub at OPENVIKING_ENDPOINT with the placeholder key" "searched_with_key $ID-s"
check "logs show no error loading the memory provider" "! all_logs $ID-h | grep -i -E 'memory provider|openviking' | grep -i -E 'error|fail|traceback|not found|could not'"
check "no runtime plugin install under /opt/data/plugins" "docker exec $ID-h test ! -e /opt/data/plugins/openviking"
echo "-- stub requests"
stub_log $ID-s | python3 -I -c '
import json, sys
for e in map(json.loads, sys.stdin):
    print(e["port"], e["method"], e["path"][:70], "x-api-key=" + e["headers"].get("x-api-key", "-"))
'
echo "-- log lines about the provider"
all_logs $ID-h | grep -i -E 'openviking|memory provider|compat|deprecat' | cut -c1-300 | head -30
echo "== result: FAIL=$FAIL"
exit $FAIL
